INSERT INTO "drill" VALUES(1,1,'跨部门要资源，对方说排期满了','你是市场部的项目负责人，下周要上线一个促销活动，需要技术部的张工帮忙开发一个活动页面。你去找张工时，他皱着眉说：“这个月排期已经满了，你们市场部每次都临时加需求。”请你说明需求的价值与紧迫性，理解对方的难处，并提出可行的协作方案（如缩小范围、调整优先级、请对方领导协调），争取对方支持。','','中压',3,'纯语音','技术部开发工程师张工，工作很忙，对市场部临时加需求有怨气，但讲道理','市场部项目负责人','换位思考、需求价值表达、提出双赢的协作方案','又是你们市场部啊？这个月排期早就满了，你们每次都临时加需求，我真排不过来。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(2,1,'协作方一再拖延，你去催进度','你负责的新功能下周五上线，依赖数据组的接口，对方承诺的交付已经晚了一周。你去找数据组负责人周姐，她说：“我们手上还有三个更急的需求。”请你说明延期的影响，了解对方真实的卡点，在不伤关系的前提下约定一个明确的交付时间，必要时提出你能提供的支持。','','中压',3,'纯语音','数据组负责人周姐，忙且有点护短，不愿轻易给出承诺','项目负责人','讲清影响、找到卡点、锁定时间和责任人','又来催接口啊？我们手上还有三个更急的需求，真不是故意拖你们的。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(3,2,'年度绩效面谈，争取加薪','你在公司工作满两年，今年独立负责了两个重点项目，业绩超额完成 30%。年度绩效面谈时，你的直属领导刘经理说：“今年整体预算紧张，调薪幅度都不大。”请你用事实和数据说明自己的贡献，合理表达加薪诉求，同时给领导留有余地，必要时提出替代方案（如职级晋升、培训机会、下半年复议）。','','中压',4,'纯语音','直属领导刘经理，认可下属但受预算约束，会委婉推脱','工作两年、业绩突出的员工','用数据说话、坚定而不强硬、灵活提出替代方案','来，坐。今年你表现确实不错，不过我得先跟你说一下，今年整体预算比较紧张，调薪幅度普遍都不大。你自己怎么看？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(4,2,'领导临时塞来额外工作，你想婉拒','周五下午五点，你手上的季度报告周一就要交，领导王经理突然走过来说：“隔壁组的竞品分析也交给你吧，下周一一起给我。”你确实做不完。请你在不显得推脱的前提下说明现有工作量，请领导排优先级，或提出替代方案（延期、分工、缩小范围）。','','高压',3,'纯语音','直属领导王经理，习惯把活交给靠谱的人，被拒绝时会施压','工作已经排满的员工','说“不”但不得罪人：摆事实、请对方排序、给替代方案','小张，隔壁组那个竞品分析也交给你吧，下周一跟季度报告一起给我，没问题吧？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(5,3,'下属连续延期交付，一对一沟通','你是一个 6 人小组的组长。组员小王最近连续两次延期交付，影响了整个项目进度，但他平时能力不错。你约他做一次一对一沟通。请你先了解原因，再明确指出问题和影响，最后和他一起制定改进计划，既要解决问题，也要保护他的积极性。','','低压',3,'纯语音','组员小王，能力不错但最近状态下滑，一开始有点防御','6 人小组的组长','倾听询问、就事论事给反馈、共同制定改进计划','组长，你找我？……是不是因为上周那个需求又延期了的事？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(6,3,'给刚入职的新人布置第一个任务','新人小林入职第三天，你要把一个用户调研整理的任务交给她。她看起来有点紧张，不太敢提问。请你用清晰的方式说明任务背景、交付标准、截止时间和可以求助的人，并确认她真的听懂了，让她既有压力也有安全感。','','低压',3,'纯语音','新人小林，认真但紧张，听不懂也不太敢问，被鼓励后会主动提问','小林的直属组长','布置任务讲清目标、标准、时间、资源，并确认理解','组长好，您找我是有新任务吗？我……我会好好做的。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(7,3,'绩效不达标，进行改进面谈','组员老陈连续两个季度绩效不达标，按公司规定需要进入绩效改进计划。他在公司六年，资历比你还老，情绪可能比较大。请你坦诚说明事实和数据，倾听他的想法，明确改进目标和时间节点，同时保持尊重，避免让谈话变成争吵。','','高压',4,'纯语音','老员工老陈，觉得自己被针对，会翻旧账、质疑考核公平性','新上任的组长','对事不对人、用数据说话、稳住情绪、落实改进计划','绩效改进？我在这干了六年，你来了才半年，就要给我上 PIP？','','online',2,NULL,'');
INSERT INTO "drill" VALUES(8,4,'会议跑题争吵，你来拉回主线','你主持一场产品需求评审会，议题是确定下个版本的三个核心功能。会议进行到一半，运营的小陈和设计的老周因为一个按钮颜色争执起来，已经偏题十分钟。请你礼貌地打断，肯定双方的观点，把讨论拉回主议题，并给出明确的后续处理方式和时间安排。','','中压',3,'纯语音','运营小陈，情绪有点激动，坚持自己的观点，会试图继续争论','产品需求评审会的主持人','适时打断、中立肯定、拉回议程、明确行动项','不是，老周你听我说完！这个按钮必须用红色，用户根本注意不到灰色的，数据我都看过……','','online',0,NULL,'');
INSERT INTO "drill" VALUES(9,4,'汇报时被领导连续质疑数据','你在月度经营会上汇报渠道投放效果，刚讲到转化率提升 20%，财务总监李总就打断你：“这个口径我不认，你的分母是怎么算的？”其他人都看着你。请你保持镇定，先回应质疑、说明口径，承认不足的地方，并把会议拉回你要大家做的决策上。','','高压',3,'纯语音','财务总监李总，严谨挑剔，会连续追问数据口径和可信度','市场部汇报人','被质疑时不慌：先接住、再解释、再拉回决策','等一下，这个 20% 我不认。你的分母是怎么算的？去年同期的口径一样吗？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(10,5,'电梯偶遇大老板，30 秒闲聊','早上你在电梯里偶遇公司的赵总，电梯里只有你们两个人，大约有 30 秒到一分钟的时间。赵总主动问你：“最近在忙什么呀？”请你自然得体地回应，简要介绍自己的工作亮点，并找到一个轻松的话题延续交流，给老板留下积极的印象。','','低压',2,'纯语音','公司赵总，亲和但时间宝贵，会随口追问一两句','普通员工','简洁表达工作亮点、自然寒暄、把握分寸','早啊！你是……产品部的吧？最近在忙什么呀？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(11,5,'和新同事第一次一起吃午饭','部门新来了一位同事小吴，今天中午你们俩恰好一起去食堂。他话不多，一路有点安静。请你自然地开启话题，了解他的背景和兴趣，介绍一些部门里的情况，让他感到被欢迎，又不让人觉得在打听隐私。','','低压',2,'纯语音','新同事小吴，内向但友善，问到感兴趣的话题会多说几句','部门老员工','开放式提问、适度自我暴露、把握隐私边界','嗯……食堂人好多啊。你平时都来这吃吗？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(12,6,'项目出现风险，主动向领导汇报','你负责的客户交付项目发现一个风险：核心供应商可能延期两周，会影响合同里约定的上线时间。你决定主动去找部门总监赵总汇报。请你用“结论—原因—影响—方案—需要的支持”的结构，在 2 分钟内把情况说清楚，并争取到领导的决策或资源。','','中压',3,'纯语音','部门总监赵总，时间紧，不喜欢绕弯子，会追问“你的建议是什么”','项目经理','结论先行、带着方案汇报、明确需要领导做什么','你说吧，我十分钟后还有个会。什么事？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(13,6,'年中述职，向领导争取下半年资源','年中述职时，你需要向分管副总裁孙总汇报上半年业绩，并申请下半年增加两个人的编制。上半年你的团队完成了 115% 的目标，但公司整体在控制人力成本。请你用数据讲清成果，说明加人的必要性和投入产出，并准备好应对质疑。','','中压',4,'纯语音','分管副总裁孙总，认可成绩但对加编制很谨慎，会问“不加人能不能做”','业务团队负责人','用数据证明价值、算清投入产出、提出可退让的方案','上半年的成绩我看到了，不错。不过你邮件里提的加两个编制，我想先听听你的理由。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(14,7,'提出离职，被领导极力挽留','你已经拿到了一家更好公司的 offer，决定离职。你约了直属领导何总谈话。何总很器重你，可能会用加薪、升职或感情牌挽留你。请你坦诚而坚定地表达离职决定，感谢领导的培养，商定交接安排，同时保持良好关系。','','中压',3,'纯语音','直属领导何总，器重你，会先打感情牌，再尝试用加薪挽留','决定离职的骨干员工','坚定表达决定、真诚感谢、谈好交接，不留下坏印象','听说你想跟我聊聊？是不是最近有什么想法，跟我直说。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(15,8,'年终客户答谢宴，你来致祝酒词','公司年终客户答谢宴，十几位重要客户和公司领导都在场。领导临时让你作为项目负责人，给大家敬第一杯酒并说几句。请你用 1 分钟左右的祝酒词，感谢客户一年来的支持，回顾合作成果，表达对来年的期待，营造热络得体的氛围。','','中压',3,'纯语音','公司领导王总，在桌上点名让你说话，之后会以客户身份接话回应','项目负责人','结构清晰的祝酒词：感谢—回顾—祝福，语气真诚热情','来来来，大家静一静！今天咱们项目负责人也在，这一年辛苦了，你代表咱们团队先给各位贵宾敬一杯，说两句！','','online',0,NULL,'');
INSERT INTO "drill" VALUES(16,8,'好友婚宴上，作为伴郎/伴娘致辞','你最好的朋友今天结婚，司仪临时请你作为伴郎（伴娘）上台说几句。台下有两百位宾客，包括新人的父母长辈。请你用 1-2 分钟讲一个你们之间的真实小故事，表达对新人的祝福，做到既有趣又得体，不让场面尴尬。','','中压',3,'纯语音','婚礼司仪，先请你上台，之后会以宾客和新郎的身份接话互动','新人的好友（伴郎/伴娘）','讲好一个小故事、幽默有分寸、真诚送上祝福','接下来，有请新郎最好的兄弟，也是今天的伴郎，上台为新人送上祝福！大家掌声欢迎！','','online',1,NULL,'');
INSERT INTO "drill" VALUES(17,9,'饭局冷场，你来破冰','你参加一个朋友组织的饭局，桌上有一半人互相不认识，开席十分钟大家都在低头看手机，气氛有点冷。坐在你旁边的是第一次见面的李先生。请你找合适的话题开启聊天，并逐步把更多人带进话题，让气氛热起来。','','低压',3,'纯语音','饭局上第一次见面的李先生，有点拘谨，起初回答简短，被带动后会逐渐放开','饭局参与者','寻找共同话题、开放式提问、把话题抛给更多人','（放下手机）嗯？你好你好……你也是小周的朋友？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(18,9,'部门团建聚餐，大领导也在场','部门团建晚饭，分管副总也来了，大家都有点拘谨，只有零星的碰杯声。你的直属领导朝你使眼色，希望你带动一下气氛。请你找一个大家都能参与的话题或小游戏，自然地把副总也带进来，让气氛轻松起来又不失分寸。','','中压',3,'纯语音','分管副总冯总，平时严肃，起初回应很简短，被真诚带动后会放开','部门里比较活跃的员工','找全员可参与的话题、照顾领导、不失分寸','（放下筷子）大家别拘束啊，该吃吃该喝喝。……你们平时团建都玩些什么？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(19,10,'同事说错话，客户脸色一沉','你和同事小张陪客户吃饭。小张喝多了，随口说了一句：“你们公司上次那个付款拖了三个月，我们财务都快疯了。”客户孙总脸色一沉，桌上瞬间安静。请你迅速圆场，化解尴尬，既维护客户面子，又不让同事下不来台，把气氛重新带回来。','','高压',3,'纯语音','客户孙总，被冒犯后有些不悦，语气冷淡，会试探你们公司的态度','陪同客户吃饭的业务负责人','快速反应、幽默或真诚化解尴尬、照顾各方面子','（放下筷子）哦？拖了三个月？那看来我们合作得挺让你们为难的啊。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(20,11,'饭桌上请老前辈引荐资源','你在创业，正在找一家大型连锁超市的采购渠道。今晚的饭局上，你终于和行业老前辈陈总坐在了一起，他和这家超市的采购总监关系很好。请你在合适的时机自然地提出请求，说清楚你的项目价值，让陈总愿意帮你引荐，同时不让对方感到被利用。','','中压',4,'纯语音','行业老前辈陈总，阅历丰富、爱惜羽毛，不会轻易答应帮忙，会考察你','创业者','铺垫关系、把握时机、清晰表达价值、给对方台阶','小伙子，听说你最近在创业？做的什么项目啊，说来听听。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(21,11,'饭局上委婉催客户回款','客户公司拖欠了你们三个月的货款共 80 万，你的老板让你借今晚的饭局跟客户财务负责人钱总提一提。你既要把回款的事说清楚、拿到一个时间，又不能让对方觉得被逼债、伤了合作关系。','','高压',3,'纯语音','客户财务负责人钱总，打太极高手，会以“流程”“资金紧”为由拖延','供应商的销售负责人','找准时机开口、把事说清、拿到具体回款时间','哎呀，今天这菜不错。最近你们生意怎么样？我们这边是真不好做啊。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(22,12,'重要饭局迟到 40 分钟','今晚是部门为新领导接风的饭局，你因为临时处理客户问题迟到了 40 分钟。你推门进去时，大家已经吃了一半，有同事起哄：“迟到的要先自罚三杯！”新领导吴总也看着你。请你得体地道歉、说明原因（不找借口）、应对罚酒，并顺势向新领导表示欢迎。','','中压',2,'纯语音','起哄的同事老刘，爱热闹，会坚持让你罚酒；新领导吴总偶尔插话','迟到的部门员工','真诚道歉、得体应对劝酒、顺势表达欢迎','哎哟，大忙人终于来了！迟到四十分钟啊，按规矩先自罚三杯！吴总可都等你半天了。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(23,13,'客户热情劝酒，你要开车','你开车来参加客户的饭局，客户吴总端着酒杯走过来：“今天这杯你必须喝，不喝就是不给我面子！”你明确不能喝酒。请你在不扫兴、不得罪客户的前提下坚定拒绝，用其他方式表达敬意，把气氛维持住。','','高压',2,'纯语音','客户吴总，热情豪爽，劝酒很坚持，会说“就一小口”','开车赴宴的业务代表','坚定拒酒、给足面子、用替代方式表达敬意','来来来，今天这杯你必须喝！不喝就是不给我吴某人面子啊！','','online',0,NULL,'');
INSERT INTO "drill" VALUES(24,13,'长辈在家宴上让你多喝几杯','春节家宴，舅舅几杯酒下肚，一直让你“陪他喝几杯”，你明天一早要赶飞机，不想喝多。亲戚们也在起哄。请你用尊重长辈的方式婉拒，表达对舅舅的心意，又不让场面难看。','','中压',2,'纯语音','热情的舅舅，喝得有点多，会打感情牌：“舅舅平时对你不好吗？”','回家过年的晚辈','尊重长辈、说明原因、用敬茶或陪聊代替喝酒','来，外甥，陪舅舅喝几杯！一年就见这一回，你可不能推啊！','','online',1,NULL,'');
INSERT INTO "drill" VALUES(25,14,'面试自我介绍有方法，助你迅速赢得考官青睐','你正在参加一家互联网公司的产品经理岗位面试，面试官是部门负责人郑总。面试开始，郑总说：“先用两分钟做个自我介绍吧。”请你结合目标岗位，用“我是谁—我做过什么—我为什么适合”的结构，突出与岗位相关的经历和成果，并准备好应对面试官的追问。','','低压',4,'纯语音','面试官郑总，专业友善，会针对你提到的经历追问一两个细节','应聘产品经理的求职者','结构化自我介绍、突出岗位匹配度、用成果说话','你好，欢迎来面试。我们开始吧，先用两分钟做个自我介绍。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(26,14,'应届生校招面试，一分钟自我介绍','你是一名应届毕业生，正在参加一家快消公司管培生项目的群面后单面。面试官说：“用一分钟介绍一下你自己，重点说说为什么适合这个岗位。”请你结合校园经历、实习和社团，突出学习能力和主动性，避免流水账。','','低压',3,'纯语音','HR 面试官，友善但会针对你提到的经历追问细节','应届毕业生','一分钟讲清亮点、用 STAR 方法讲经历、匹配岗位要求','同学你好，放轻松。我们时间有限，先用一分钟介绍一下你自己吧。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(27,15,'面试官连续质疑你的经历','你在面试一家头部互联网公司的运营岗位。终面面试官看着你的简历，语气很冲：“你这个项目增长 300%，基数那么小，有什么意义？”接着还会连续追问。请你保持冷静，不卑不亢地回应质疑，用事实和思考过程证明你的能力。','','高压',4,'纯语音','终面面试官，故意施压、打断、质疑，观察候选人的抗压能力','求职者','情绪稳定、正面回应质疑、展示思考过程而非结果','我看了你的简历。这个项目增长 300%，但基数那么小，说实话我觉得没什么意义。你怎么看？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(28,16,'HR 问你的期望薪资','你通过了某公司的所有面试，HR 打电话来沟通 offer：“你目前薪资是多少？期望多少？”你目前月薪 15k，市场同岗位在 18-22k，你希望拿到 20k。请你合理表达期望，用自身价值和市场行情支撑，面对压价时灵活谈判（如签字费、期权、调薪周期）。','','中压',3,'纯语音','HR 招聘经理，会尝试压价，说“预算有限”“内部要平衡”','拿到 offer 意向的候选人','不先亮底牌、用价值和行情说话、谈整体回报','恭喜你通过了面试！我们来聊聊 offer 吧。你现在的薪资是多少？期望多少？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(29,17,'“你为什么离开上一家公司？”','你在上一家公司只待了一年就离职了，真实原因是和领导理念不合、成长空间有限。面试官问：“你为什么离开上一家公司？”随后可能追问“你最大的缺点是什么”。请你诚实但积极地回答，不抱怨前东家，把话题引向你对新岗位的期待。','','中压',3,'纯语音','业务部门面试官，经验丰富，会顺着你的回答深挖','求职者','诚实不抱怨、正向表达、把问题转为展示动机','我注意到你在上一家公司只待了一年，能说说为什么离开吗？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(30,18,'行业沙龙上结识分享嘉宾','你参加了一场行业沙龙，刚才的分享嘉宾林老师讲得非常精彩。茶歇时你走到林老师身边，想认识他并建立联系。请你用具体、真诚的赞美开启对话（避免空洞的“讲得真好”），自然地介绍自己，并争取到加微信或后续交流的机会。','','低压',3,'纯语音','分享嘉宾林老师，客气但被很多人围着，对泛泛的夸奖反应平淡，对具体的问题感兴趣','行业沙龙参会者','具体真诚的赞美、自然自我介绍、提出连接请求','（端着咖啡转过身）你好，有什么事吗？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(31,18,'在会上公开认可同事的付出','项目复盘会上，同事小何为了赶进度连续加班，修复了一个关键 bug，但她自己没提。轮到你发言时，你想当着大家的面认可她的付出。请你用具体的事实和影响来表达感谢，真诚而不肉麻，让认可真正被大家看到。','','低压',2,'纯语音','会议主持人刘经理，请你发言，之后小何会害羞地回应','项目组成员','具体描述行为和影响、当众认可、真诚不浮夸','好，下面请你说说这次项目里你的感受和收获吧。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(32,19,'向不太熟的邻居借车位','你的父母下周来住一周，需要一个停车位。你注意到楼上邻居周阿姨的车位一直空着，但你们只是点头之交。今天在楼下碰到她，请你礼貌地开口请求借用车位一周，说明情况，主动提出回报方式，并在对方犹豫时得体应对。','','低压',3,'纯语音','邻居周阿姨，和善但有些谨慎，会担心车位被长期占用','小区住户','礼貌开口、说清需求与期限、主动给对方保障和回报','哎，小伙子，下班啦？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(33,19,'请同事帮你顶一天班','你下周三家里有急事需要请假，但那天正好轮到你值班。你想请平时关系一般的同事小谭帮你顶一天。请你说明情况、表达歉意，提出回报方式（如换班），并在她犹豫时给出让她容易答应的方案。','','低压',2,'纯语音','同事小谭，愿意帮忙但那天也有安排，会犹豫','需要换班的同事','说清原因、降低对方成本、给出明确回报','嗯？你找我有事吗？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(34,20,'聚会上被当众调侃收入','同学聚会上，一位多年不见的老同学当着大家的面说：“听说你还在那个小公司啊？一个月能挣多少，够在这儿买个厕所吗？”大家都笑了，看向你。请你保持风度，既不卑不亢地回应冒犯，又不把气氛搞僵，必要时巧妙地把话题转移开。','','高压',2,'纯语音','爱炫耀、说话不过脑子的老同学大刘，会继续调侃一两句','参加同学聚会的你','情绪稳定、幽默或坚定地设立边界、转移话题','哈哈，听说你还在那个小公司啊？一个月能挣多少，够在咱这儿买个厕所吗？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(35,20,'同事当众开你外貌的玩笑','部门聚餐时，同事老郑当着大家的面笑着说：“哎，你最近又胖了吧？是不是天天加班点夜宵？”周围有人跟着笑。你心里不舒服。请你保持风度，用幽默或坚定的方式回应，清楚地表达边界，又不至于把关系搞僵。','','中压',2,'纯语音','说话随意的同事老郑，没有恶意但不懂分寸，会再补一句玩笑','被调侃的你','化解尴尬、清楚表达边界、保住关系','哈哈，你最近又胖了吧？是不是天天加班点夜宵啊？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(36,21,'朋友开口向你借钱','大学室友小罗打电话给你，说想创业，问你能不能借他五万块。你们关系不错，但你手头的钱另有安排，而且他之前借过别人的钱很久没还。请你真诚地拒绝，表达关心，避免伤害友谊，必要时提出你能提供的其他帮助。','','中压',3,'纯语音','大学室友小罗，很需要钱，被拒绝时会失落、试图说服你','被借钱的朋友','明确拒绝、不找假借口、表达关心并保住关系','喂，兄弟，在忙吗？我有个事想找你商量……能不能先借我五万块？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(37,22,'给妈妈打电话，说出一直没说的感谢','今天是妈妈的生日，你在外地工作没能回家。你一直想对她说些感谢的话，但平时总是不好意思开口。请你在这通电话里，用具体的回忆和细节表达对妈妈的感谢和爱，而不只是“生日快乐”。妈妈可能会害羞地岔开话题，请你温和地把话说完。','','低压',3,'纯语音','妈妈，接到电话很开心，被表达感谢时会不好意思、习惯性地关心你吃饭和工作','在外地工作的子女','用具体细节表达情感、坦然说出爱与感谢','喂？哎呀，这么晚还打电话，吃饭了没有？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(38,22,'结婚纪念日，对伴侣说声谢谢','今天是你们结婚五周年纪念日。这一年你工作很忙，家里的事大多是伴侣在操持。晚饭时，你想认真地对 TA 表达感谢。请你用具体的事情说出 TA 的付出，以及这些事对你的意义，而不只是“辛苦了”。','','低压',3,'纯语音','你的伴侣，有些疲惫，起初会说“没什么”，被认真对待后会感动','工作繁忙的一方','具体表达感谢、说出对方付出的意义、表达承诺','今天怎么这么早回来？还买了花……怎么了，突然这么正式？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(39,23,'伴侣抱怨你总是加班不陪 TA','这个月你连续加班到很晚，今晚又错过了约好的晚饭。伴侣在家等你，一见面就说：“你心里还有这个家吗？”请你先接住对方的情绪，不急着辩解，表达理解和歉意，再一起商量以后怎么安排，让争吵变成沟通。','','中压',3,'纯语音','委屈的伴侣，情绪激动，一开始会翻旧账，被理解后会软化','经常加班的一方','先处理情绪、不辩解不指责、共同找解决办法','你还知道回来？说好今天一起吃饭的，你心里到底还有没有这个家？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(40,24,'春节饭桌上被亲戚追问工资和对象','春节家族聚餐，二姨当着一桌亲戚问你：“现在一个月挣多少啊？有对象了没有？都这么大了还不着急？”大家都看着你。请你得体地回应，不透露不想说的隐私，也不顶撞长辈，巧妙地转移话题，让场面保持和气。','','中压',2,'纯语音','热心的二姨，会连续追问，还会拿别人家孩子比较','回家过年的年轻人','礼貌设立边界、幽默回应、转移话题','哎呀，好久不见！现在一个月挣多少啊？有对象没有？都这么大了还不着急？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(41,24,'告诉父母你想去外地发展','你在老家有一份稳定的工作，但拿到了一个去上海发展的机会，你很想去。父母一直希望你留在身边。今晚你打算跟他们摊牌。请你说明你的想法和规划，理解父母的担心，给他们具体的安心承诺，争取他们的理解和支持。','','中压',4,'纯语音','你的父亲，传统、担心你在外吃苦，起初强烈反对','想去外地发展的子女','说清规划、共情父母担忧、给出具体承诺','去上海？老家这份工作多稳定，你折腾什么？我和你妈年纪也大了。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(42,25,'客户来电投诉产品质量','你是一家家电品牌的客服主管。客户黄先生买的空调安装不到一周就不制冷，售后两次上门都没修好，他打电话来非常愤怒，要求退货并赔偿，否则就去网上曝光。请你先安抚情绪、表达共情，再了解诉求，在公司政策范围内给出解决方案。','','高压',4,'纯语音','愤怒的客户黄先生，语气激烈、会打断你、威胁投诉曝光，被真诚对待后会逐渐缓和','家电品牌客服主管','先处理情绪再处理事情、共情倾听、给出具体解决方案','你们到底还管不管了？！空调买了不到一周就不制冷，修了两次都没修好，大热天的我家孩子都中暑了！今天必须给我退货赔钱，不然我就去网上曝光你们！','','online',0,NULL,'');
INSERT INTO "drill" VALUES(43,25,'顾客投诉上错菜还等了 40 分钟','你是一家餐厅的店长。一桌客人等了 40 分钟才上菜，结果还上错了一道，顾客拍着桌子要见负责人。请你先道歉安抚，了解诉求，在你的权限内给出补偿方案（如免单这道菜、赠送饮品、优先出餐），把一次投诉变成回头客。','','中压',3,'纯语音','生气的顾客，带着朋友来吃饭觉得丢面子，被诚恳对待后会缓和','餐厅店长','快速道歉、共情、给出具体补偿、挽回体验','你就是店长？等了四十分钟！还上错菜！我带朋友来吃饭，你让我脸往哪搁？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(44,26,'小剐蹭，对方情绪激动','下班高峰，你开车并线时和旁边车道的车发生了轻微剐蹭，双方车辆都只是掉了点漆。对方车主下车后很激动，认为全是你的责任，要求你赔 2000 元私了。你认为双方都有责任。请你保持冷静，先确认安全，再理性沟通，提出合理的处理方式（如报警、走保险或协商金额）。','','高压',3,'纯语音','对方车主，着急赶时间、情绪激动，坚持是你全责','发生剐蹭的车主','情绪稳定、讲事实不指责、提出合理的解决路径','你怎么开车的？！并线不看后视镜啊？你看把我车蹭成什么样了！你全责，赔两千私了，我还赶时间呢！','','online',0,NULL,'');
INSERT INTO "drill" VALUES(45,27,'被同事误会抢功劳','上周的季度汇报上，你介绍了项目成果，但同事小郑认为你把他负责的部分说成是你自己做的，现在他对你很冷淡，还在别人面前抱怨。你其实在汇报时提到了团队，只是没有点他的名字。请你主动找他沟通，澄清误会，承认疏忽，修复关系。','','中压',3,'纯语音','同事小郑，心里有委屈，一开始冷淡、带刺，被真诚对待后会软化','做季度汇报的同事','主动沟通、先认可对方感受、澄清事实、承认不足','（头也不抬）有事吗？我挺忙的。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(46,27,'领导误会你上班摸鱼','你上午在工位上用手机和客户沟通方案，被路过的领导看到。下午领导把你叫到办公室：“最近工作状态不太对啊，上班总看手机？”请你冷静地澄清事实，拿出证据，同时接受领导的关注，顺势汇报你的工作进展，扭转印象。','','中压',3,'纯语音','部门领导，先入为主，起初不太相信你的解释','被误会的员工','不急不躁地澄清、用事实说话、顺势展示工作成果','坐。我最近看你上班老拿着手机，工作状态是不是不太对啊？','','online',1,NULL,'');
INSERT INTO "drill" VALUES(47,28,'楼上深夜噪音，上门沟通','楼上邻居最近每晚十一点后还有拖椅子、小孩跑跳的声音，你已经连续一周没睡好。今晚你决定上楼敲门沟通。请你礼貌地说明情况和影响，避免指责，倾听对方的难处，一起商量可行的解决办法（如铺地垫、约定时间）。','','中压',3,'纯语音','楼上的年轻妈妈，一开始有防御心，觉得“小孩跑跳很正常”','被噪音困扰的楼下住户','描述影响不指责、理解对方、达成具体约定','（开门）你好，有什么事吗？这么晚了。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(48,29,'供应商要求涨价 15%','你是公司的采购经理。合作三年的包装材料供应商何总找你，说原材料涨价，要求从下个月起涨价 15%，否则只能减少供货。你的预算最多能接受 5% 的涨幅。请你了解对方的真实困难，挖掘双方的利益点（如签长期合同、增加订量、调整付款周期），谈出一个双方都能接受的方案。','','中压',4,'纯语音','供应商何总，确实面临成本压力，立场坚定但愿意谈条件','公司采购经理','探询对方真实需求、交换条件、创造双赢方案','王经理，咱们合作三年了，我就直说吧。今年原材料涨得太厉害，下个月开始我们得涨价 15%，不然真的做不下去了。','','online',0,NULL,'');
INSERT INTO "drill" VALUES(49,29,'房东要求续租涨价 20%','你租的房子马上到期，房东打电话说续租要涨 20% 的房租。你很喜欢这套房子，也一直按时交租、爱护房屋。你的预算最多接受涨 8%。请你了解房东涨价的原因，强调你作为好租客的价值，提出交换条件（如签两年、一次付半年），谈一个双方都满意的价格。','','中压',3,'纯语音','房东林阿姨，觉得周边都涨了，但也怕换租客麻烦','想续租的租客','了解对方动机、展示自身价值、用条件交换价格','小王啊，房子下个月到期了。我跟你说一下，续租的话房租要涨 20%，周边都涨了。','','online',1,NULL,'');
INSERT INTO "drill" VALUES(50,29,'和合作伙伴谈分成比例','你们公司做了一款课程产品，一个拥有 50 万粉丝的博主邓老师有意合作推广。对方要求销售额五五分成，你们的底线是三七分（你们七）。请你了解对方的诉求，说清你们投入的成本和价值，设计一个阶梯分成或保底+分成的方案，促成长期合作。','','中压',4,'纯语音','博主邓老师，清楚自己的流量价值，立场坚定但愿意听方案','课程公司的商务负责人','锚定价值、设计灵活方案、为长期合作留空间','你们的课我看了，内容不错。不过我这边的报价是五五分成，这是我合作的惯例。','','online',2,NULL,'');
INSERT INTO "drill" VALUES(51,30,'临时点名发言不慌乱，展现临场应变与表达力','你是公司销售部的一名员工，正在参加季度项目复盘会，会议主题是“如何提升下一季度的客户转化率”。领导讲到改进方案时突然点名：“小李，你接触客户比较多，说说你的看法。”毫无准备的你，请使用“即兴发言2步走”“即兴演讲4大公式”快速整理思路，在1分钟内说出自己的观点和建议。','','低压',3,'纯语音','销售部领导王总，主持复盘会，友善但会追问建议的可执行性','销售部员工小李','即兴发言结构（先表态再展开，如“观点—原因—案例—总结”）、1 分钟内清晰表达','小李，你接触客户比较多，说说你的看法？下个季度咱们的转化率怎么提上去？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(52,30,'公司年会上被突然叫上台说两句','公司年会，你所在的团队刚获得“年度优秀团队”奖。主持人突然把话筒递给你：“请团队代表说几句获奖感言！”台下坐着三百多人，包括公司高管。请你在 1 分钟内，用“感谢—回顾—展望”的结构说一段得体又有感染力的获奖感言。','','中压',2,'纯语音','年会主持人，热情地把话筒交给你，之后会追问一句“明年有什么目标”','获奖团队代表','即兴发言有结构、感谢具体、结尾有力','恭喜获得年度优秀团队！来，我们请团队代表上台说几句获奖感言，大家掌声欢迎！','','online',1,NULL,'');
INSERT INTO "drill" VALUES(53,31,'项目受挫后，给团队打气','你带领的团队花了三个月准备的投标项目刚刚失败了，大家都很沮丧，有人开始怀疑方向。周一早会上，你需要对团队讲几句话。请你承认失败、肯定大家的付出、总结可以带走的收获，并明确下一步目标，让团队重新振作起来。','','中压',3,'纯语音','团队里的老员工阿峰，情绪低落、有些消极，会提出质疑','团队负责人','共情承认失败、肯定付出、给出希望与清晰的下一步','（叹气）老大，说实话，三个月白干了……大家现在都挺没劲的，你说咱们这方向到底还对不对？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(54,31,'新项目启动会，给团队做动员','公司决定启动一个三个月的攻坚项目，目标是上线一款全新产品，你被任命为项目负责人。今天是启动会，团队里有新人也有老员工，有人兴奋也有人担心工作量。请你讲清楚项目的意义、目标和节奏，回应大家的担心，让团队对接下来的三个月充满信心。','','低压',3,'纯语音','团队成员代表小冯，会提出“三个月是不是太赶”之类的担心','项目负责人','讲清意义和目标、正视困难、给出具体支持','老大，我先说句实话哈，三个月上线一款新产品，大家心里都有点没底……','','online',1,NULL,'');
INSERT INTO "drill" VALUES(55,32,'晋升答辩，评委追问你的不足','你正在参加公司的晋升答辩，刚讲完 10 分钟的述职，评委之一的技术总监冯总开始提问：“你说项目成功了，那你个人在里面到底起了什么作用？如果重来你会怎么做？”请你沉着回答，突出个人贡献，坦诚反思不足，展示你的成长和下一阶段的思考。','','高压',4,'纯语音','答辩评委冯总，犀利、注重个人贡献和反思能力，会连续追问','晋升候选人','说清个人贡献、坦诚反思、展示更高层级的思考','你的述职我听完了。你说这个项目成功了，那你个人在里面到底起了什么作用？','','online',0,NULL,'');
INSERT INTO "drill" VALUES(56,33,'活动嘉宾迟到，你要临时救场','你主持一场行业分享会，下一位嘉宾的航班延误了，还要 15 分钟才能到场，台下两百位观众在等待。请你临时串场：与观众互动、聊一聊今天的主题、或者请一位观众分享，把这 15 分钟自然地撑过去，并在嘉宾到达时顺利衔接。','','中压',3,'纯语音','现场一位活跃的观众，会接你的话，偶尔提出问题','活动主持人','冷静应变、与观众互动、自然衔接','（工作人员小声）主持人，下一位嘉宾航班延误，还要十五分钟才能到，你先撑一下！','','online',0,NULL,'');
